UPDATE event_dispatch_job
SET dispatch_status = #{completedStatus}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND dispatch_status = 'DISPATCHING'

UPDATE event_dispatch_job
SET dispatch_status = #{failedStatus}
WHERE id = #{id, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
  AND dispatch_status = 'DISPATCHING'
